#include <common/include/Stream.h>
#include "h2cov/include/h2cov.h"
#include <testsupport/include/test_utils.h>
#include "unity.h"

using namespace ranging;

static const float TEST_EPSILON = 1.0e-4f;


void test_h2cov() {
	TRACE();


	ComplexF _Hest[] = {
			ComplexF(-0.758453297283692, -0.196861446475943),
			ComplexF(-1.10961303850152,   0.586442621667069),
			ComplexF(-0.845551240007797, -0.851886969622469),
			ComplexF(-0.572664866457950,  0.800320709801823),
			ComplexF(-0.558680764473972, -1.509404724734390),
			ComplexF( 0.178380225849766,  0.875874147834533), };

	Matrix<ComplexF> Hest(1, 6, _Hest);

	ComplexF _CovRef[] = {
			ComplexF(3.62983018548071, 0), ComplexF(0.967228281531539, -0.386655099365372),
			ComplexF(3.67202883488151, 0.727795005127735), ComplexF(-0.885447934411827, 0.694111178191148),
			ComplexF(0.967228281531539,	0.386655099365372), ComplexF(3.98428264002460, 0),
			ComplexF(-0.646984458749936, 1.58808110959114), ComplexF(3.46184213927840, -0.396208776588304),
			ComplexF(3.67202883488151, -0.727795005127735), ComplexF(-0.646984458749936,-1.58808110959114),
			ComplexF(4.99955341594800, 0), ComplexF(-2.50734248951324, -0.0731371479738757),
			ComplexF(-0.885447934411827, -0.694111178191148), ComplexF(3.46184213927840, 0.396208776588304),
			ComplexF(-2.50734248951324,	0.0731371479738757), ComplexF(4.35786013527581, 0), };

	Matrix<ComplexF> CovRef(4, 4, _CovRef);

	//std::cout << "Hest: " << Hest;

	msize_t L = 4;

	MatrixCmpl COV(h2cov(Hest, L));

	//std::cout << "COV: " << COV;
	//std::cout << "CovRef: " << CovRef;

	TEST_ASSERT_TRUE(test_cmp(COV, CovRef, TEST_EPSILON));

}

